      const errors = {};

      if (!values.fullName.trim()) {
        errors.fullName = "Please enter your full name.";
      }

      if (!values.email.trim()) {
        errors.email = "Please enter your email address.";
      } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email)) {
        errors.email = "Please enter a valid email address.";
      }

      return errors;
    }

    function FormField(config) {
      const isInvalid = Boolean(config.error);

      return `
        <div class="form-field">
          <label for="${config.id}">${config.label}${config.required ? " *" : ""}</label>
          <input
            id="${config.id}"
            name="${config.name}"
            type="${config.type}"
            placeholder="${config.placeholder}"
            value="${config.value}"
            ${config.required ? "required" : ""}
            ${config.autoComplete ? `autocomplete="${config.autoComplete}"` : ""}
            aria-invalid="${isInvalid}"
            ${config.helperText ? `aria-describedby="${config.id}-helper"` : ""}
          />
          ${config.helperText ? `<div class="helper-text" id="${config.id}-helper">${config.helperText}</div>` : ""}
          <div class="error-text">${config.error || ""}</div>
        </div>
      `;
    }

    function SupportContactForm(errors) {
      return `
        <form id="support-contact-form" novalidate>
          ${FormField({
            id: "full-name",
            name: "fullName",
            label: "Full name",
            type: "text",
            placeholder: "Jordan Lee",
            value: state.values.fullName,
            required: true,
            autoComplete: "name",
            error: errors.fullName
          })}
          ${FormField({
            id: "email-address",
            name: "email",
            label: "Email address",
            type: "email",
            placeholder: "jordan@example.com",
            value: state.values.email,
            required: true,
            autoComplete: "email",
            error: errors.email
