<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Support Contact Form</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1120;
      --panel: rgba(15, 23, 42, 0.92);
      --panel-border: rgba(148, 163, 184, 0.18);
      --text: #e5eefc;
      --muted: #93a4bf;
      --accent: #7c3aed;
      --accent-strong: #8b5cf6;
      --accent-soft: rgba(124, 58, 237, 0.18);
      --input-bg: rgba(15, 23, 42, 0.72);
      --input-border: rgba(148, 163, 184, 0.22);
      --danger: #fca5a5;
      --shadow: 0 30px 60px rgba(2, 6, 23, 0.5);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, rgba(124, 58, 237, 0.25), transparent 30%),
        linear-gradient(180deg, #020617 0%, #0f172a 100%);
      color: var(--text);
      display: grid;
      place-items: center;
      padding: 32px 18px;
    }

    .shell {
      width: min(100%, 960px);
    }

    .card {
      display: grid;
      gap: 28px;
      grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
      background: var(--panel);
      border: 1px solid var(--panel-border);
      border-radius: 24px;
      padding: 32px;
      box-shadow: var(--shadow);
      backdrop-filter: blur(18px);
    }

    .hero {
      display: grid;
      align-content: start;
      gap: 14px;
      padding-right: 8px;
    }

    .eyebrow {
      margin: 0;
      color: #c4b5fd;
      text-transform: uppercase;
      letter-spacing: 0.12em;
      font-size: 0.78rem;
      font-weight: 700;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 4vw, 3rem);
      line-height: 1.05;
    }

    .lead,
    .support-note {
      margin: 0;
      color: var(--muted);
      line-height: 1.65;
    }

    .support-note {
      padding: 14px 16px;
      border-radius: 16px;
      background: rgba(15, 23, 42, 0.72);
      border: 1px solid rgba(124, 58, 237, 0.16);
    }

    form {
      display: grid;
      gap: 18px;
    }

    .form-field {
      display: grid;
      gap: 8px;
    }

    label {
      font-weight: 600;
      font-size: 0.96rem;
    }

    input {
      width: 100%;
      border: 1px solid var(--input-border);
      background: var(--input-bg);
      color: var(--text);
      border-radius: 14px;
      padding: 14px 16px;
      font: inherit;
      outline: none;
      transition: border-color 180ms ease, box-shadow 180ms ease, transform 180ms ease;
    }

    input::placeholder {
      color: #64748b;
    }

    input:focus {
      border-color: rgba(139, 92, 246, 0.7);
      box-shadow: 0 0 0 4px var(--accent-soft);
    }

    input[aria-invalid="true"] {
      border-color: rgba(252, 165, 165, 0.8);
      box-shadow: 0 0 0 4px rgba(248, 113, 113, 0.12);
    }

    .helper-text,
    .error-text {
      font-size: 0.88rem;
      line-height: 1.5;
    }

    .helper-text {
      color: var(--muted);
    }

    .error-text {
      color: var(--danger);
      min-height: 1.3em;
    }

    .actions {
      padding-top: 6px;
    }

    button {
      border: 0;
      border-radius: 999px;
      background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
      color: #f8fafc;
      font: inherit;
      font-weight: 700;
      padding: 14px 22px;
      cursor: pointer;
      box-shadow: 0 14px 32px rgba(124, 58, 237, 0.35);
      transition: transform 180ms ease, box-shadow 180ms ease, filter 180ms ease;
    }

    button:hover {
      transform: translateY(-1px);
      filter: brightness(1.05);
      box-shadow: 0 18px 36px rgba(124, 58, 237, 0.4);
    }

    button:active {
      transform: translateY(0);
    }

    .status {
      margin: 4px 0 0;
      color: #bfdbfe;
      font-size: 0.92rem;
      min-height: 1.4em;
    }

    @media (max-width: 640px) {
      .card {
        padding: 24px;
        border-radius: 20px;
      }
    }
  </style>
</head>
<body>
  <div id="app"></div>

  <script>
    const state = {
      values: {
        fullName: "",
        email: "",
        phone: ""
      },
      touched: {
        fullName: false,
        email: false
      },
      status: ""
    };

    function validate(values) {
      const errors = {};

      if (!values.fullName.trim()) {
        errors.fullName = "Please enter your full name.";
      }

      if (!values.email.trim()) {
        errors.email = "Please enter your email address.";
      } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email)) {
        errors.email = "Please enter a valid email address.";
      }

      return errors;
    }

    function escapeHtml(value) {
      return String(value)
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#39;");
    }

    function FormField(config) {
      const isInvalid = Boolean(config.error);

      return `
        <div class="form-field">
          <label for="${config.id}">${escapeHtml(config.label)}${config.required ? " *" : ""}</label>
          <input
            id="${config.id}"
            name="${config.name}"
            type="${config.type}"
            placeholder="${escapeHtml(config.placeholder)}"
            value="${escapeHtml(config.value)}"
            ${config.required ? "required" : ""}
            ${config.autoComplete ? `autocomplete="${config.autoComplete}"` : ""}
            aria-invalid="${isInvalid}"
            ${config.helperText ? `aria-describedby="${config.id}-helper"` : ""}
          />
          ${config.helperText ? `<div class="helper-text" id="${config.id}-helper">${escapeHtml(config.helperText)}</div>` : ""}
          <div class="error-text">${config.error ? escapeHtml(config.error) : ""}</div>
        </div>
      `;
    }

    function SupportContactForm(errors) {
      return `
        <form id="support-contact-form" novalidate>
          ${FormField({
            id: "full-name",
            name: "fullName",
            label: "Full name",
            type: "text",
            placeholder: "Jordan Lee",
            value: state.values.fullName,
            required: true,
            autoComplete: "name",
            error: errors.fullName
          })}
          ${FormField({
            id: "email-address",
            name: "email",
            label: "Email address",
            type: "email",
            placeholder: "jordan@example.com",
            value: state.values.email,
            required: true,
            autoComplete: "email",
            error: errors.email
          })}
          ${FormField({
            id: "phone-number",
            name: "phone",
            label: "Phone number",
            type: "tel",
            placeholder: "(555) 123-4567",
            value: state.values.phone,
            required: false,
            autoComplete: "tel",
            helperText: "Optional. Use a format like (555) 123-4567 or +1 555 123 4567."
          })}
          <div class="actions">
            <button type="submit">Submit request</button>
          </div>
          <p class="status" aria-live="polite">${escapeHtml(state.status)}</p>
        </form>
      `;
    }

    function App() {
      const errors = validate(state.values);
      const visibleErrors = {
        fullName: state.touched.fullName ? errors.fullName : "",
        email: state.touched.email ? errors.email : ""
      };

      return `
        <main class="shell">
          <section class="card">
            <div class="hero">
              <p class="eyebrow">Support</p>
              <h1>Contact our support team</h1>
              <p class="lead">Send us the details below and a specialist will follow up with the right next step.</p>
              <p class="support-note">We typically respond to account, billing, and technical questions within one business day.</p>
            </div>
            <div>
              ${SupportContactForm(visibleErrors)}
            </div>
          </section>
        </main>
      `;
    }

    function render() {
      document.getElementById("app").innerHTML = App();

      const form = document.getElementById("support-contact-form");
      const inputs = form.querySelectorAll("input");

      inputs.forEach((input) => {
        input.addEventListener("input", (event) => {
          const { name, value } = event.target;
          state.values[name] = value;
          if (state.touched[name]) {
            state.status = "";
            render();
          }
        });

        input.addEventListener("blur", (event) => {
          state.touched[event.target.name] = true;
          render();
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        state.touched.fullName = true;
        state.touched.email = true;

        const errors = validate(state.values);
        if (Object.keys(errors).length > 0) {
          state.status = "Please correct the highlighted fields and try again.";
          render();
          return;
        }

        state.status = "Your support request is ready to send.";
        render();
      });
    }

    render();
  </script>
</body>
</html>
